        var ffwy = cy * CHUNK_SIZE + fy * meshGridSize;
        var fdx2 = ffwx - cStructure.centerWX, fdy2 = ffwy - cStructure.centerWY;
        // Distance metric: use Chebyshev (max of abs) for box structures, Euclidean for arena
        var sDist;
