          var _cr2 = Math.floor(85 * _cb + 25 * (1 - _cb));
          var _cg2 = Math.floor(60 * _cb + 18 * (1 - _cb));
          var _cb2 = Math.floor(40 * _cb + 10 * (1 - _cb));
