    var _plIntensity = 0.6;
    var _plEff = _plIntensity * (0.3 + 0.7 * darkFactor);
    var _plcx = Math.floor(pos.x / _lightCellSize);
    var _plcy = Math.floor(pos.y / _lightCellSize);
    var _plrCells = Math.ceil(_plRadius / _lightCellSize);
