    c.bezierCurveTo(hdX + hR * 0.58, hdY + hR * 0.06, hdX + hR * 0.38, hdY + hR * 0.06, hdX + hR * 0.3, hdY - hR * 0.08);
    c.closePath(); c.fill();
    c.fillStyle = noseCol;
    c.beginPath(); c.ellipse(hdX + hR * 0.48, hdY - hR * 0.08, hR * 0.04, hR * 0.1, 0, 0, Math.PI * 2); c.fill();
