    c.fillStyle = fur;
    c.beginPath();
    c.moveTo(cx1 + bw1 * 0.2, cy1 - bh1 * 0.3);
    c.quadraticCurveTo(hx1 - hr1 * 0.5, hy1 + hr1 * 0.8, hx1 - hr1 * 0.3, hy1 + hr1 * 0.4);
