    c.fillStyle = furDark;
    c.beginPath(); c.ellipse(cx3, cy3 - bh3 * 0.45, bw3 * 0.6, bh3 * 0.3, 0.15, 0, Math.PI * 2); c.fill();
    // Near legs (over body)
