    c.strokeStyle = fur; c.lineWidth = 3.5; c.lineCap = 'round';
    c.beginPath(); c.moveTo(tx3, ty3);
    c.bezierCurveTo(tx3 - 4, ty3 - 6 + wag * 0.2, tx3 - 8, ty3 - 14 + wag * 0.5, tx3 - 5, ty3 - 22 + wag);
    c.stroke();
    c.strokeStyle = furLight; c.lineWidth = 2;
