  pc.lineWidth = 1.5;
  var _zeroY = yAt(0);
  pc.beginPath(); pc.moveTo(margin.left, _zeroY); pc.lineTo(W - margin.right, _zeroY); pc.stroke();
  pc.fillStyle = '#77aa77';
  pc.font = '9px monospace';
  pc.fillText('surface', W - margin.right - 40, _zeroY - 3);

